    var ySel=el('year'),mSel=el('month'),oldY=ySel.value,oldM=mSel.value;
    ySel.innerHTML='<option value="">Año: Todos</option>'+Object.keys(years).sort().reverse().map(function(y){return '<option value="'+safe(y)+'">Año: '+safe(y)+'</option>';}).join('');
    mSel.innerHTML='<option value="">Mes: Todos</option>'+Object.keys(months).sort().map(function(m){var lbl=['','Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'][parseInt(m,10)]||m;return '<option value="'+safe(m)+'">Mes: '+safe(lbl)+'</option>';}).join('');
