      Array.from(document.querySelectorAll('.status-seg button')).forEach(function(b){b.onclick=function(){activeStatus=b.getAttribute('data-status')||'';Array.from(document.querySelectorAll('.status-seg button')).forEach(function(x){x.classList.toggle('on',x===b);});page=1;render();};});
      Array.from(document.querySelectorAll('.origin-seg button')).forEach(function(b){b.onclick=function(){var v=b.getAttribute('data-origin')||'';activeOrigen=(activeOrigen===v?'':v);Array.from(document.querySelectorAll('.origin-seg button')).forEach(function(x){x.classList.toggle('on',(x.getAttribute('data-origin')||'')===activeOrigen);});page=1;render();};});
